WITH base_bal AS (    SELECT        CTACTB,        SUM(CASE WHEN REFERENCIA <= LAST_DAY(DATE(:VAR_DATA_REF_DRE)) THEN VLRLANC ELSE 0 END) AS total_atu,        SUM(CASE WHEN YEAR(REFERENCIA) = YEAR(DATE(:VAR_DATA_REF_DRE)) AND REFERENCIA <= LAST_DAY(DATE(:VAR_DATA_REF_DRE)) THEN VLRLANC ELSE 0 END) AS ytd_atu,        SUM(CASE WHEN REFERENCIA <= LAST_DAY(DATE_SUB(DATE(:VAR_DATA_REF_DRE), INTERVAL 1 YEAR)) THEN VLRLANC ELSE 0 END) AS total_ant,        SUM(CASE WHEN YEAR(REFERENCIA) = YEAR(DATE_SUB(DATE(:VAR_DATA_REF_DRE), INTERVAL 1 YEAR)) AND REFERENCIA <= LAST_DAY(DATE_SUB(DATE(:VAR_DATA_REF_DRE), INTERVAL 1 YEAR)) THEN VLRLANC ELSE 0 END) AS ytd_ant,        SUM(CASE WHEN REFERENCIA < MAKEDATE(YEAR(DATE(:VAR_DATA_REF_DRE)), 1) THEN VLRLANC ELSE 0 END) AS saldo_final_ano_anterior,        SUM(CASE WHEN REFERENCIA < MAKEDATE(YEAR(DATE_SUB(DATE(:VAR_DATA_REF_DRE), INTERVAL 1 YEAR)), 1) THEN VLRLANC ELSE 0 END) AS saldo_final_ano_retrasado    FROM IMP_BASE_BALANCETE    WHERE CODEMP = :VAR_EMPRESA_DRE    GROUP BY CTACTB),regras_contas AS (    SELECT DISTINCT        DET.ORDEM,        DET.NOME_GRUPO,        DET.COD_NOTA_EXPLICATIVA,        DETCTACTB.PADRAO_CTACTB,        DETCTACTB.SINAL    FROM ESTR_DEMONSTRATIVOS EST    INNER JOIN DET_DEMONSTRATIVO DET ON EST.ID = DET.ID_ESTR_DEMONSTRATIVO    INNER JOIN DET_DEMONSTRATIVO_REFERENCIA DETREF ON DET.ID = DETREF.ID_DET_DEMONSTRATIVO    INNER JOIN DET_DEMONSTRATIVO_CTACTB DETCTACTB ON DETREF.ID = DETCTACTB.ID_DET_DEMONSTRATIVO_REFERENCIA    WHERE EST.ID = 1      AND DET.ORDEM <> '3.3.3'      AND DETREF.ANO_REFERENCIA = (          SELECT MAX(R.ANO_REFERENCIA)          FROM DET_DEMONSTRATIVO_REFERENCIA R          WHERE R.ID_DET_DEMONSTRATIVO = DET.ID            AND R.ANO_REFERENCIA <= YEAR(DATE(:VAR_DATA_REF_DRE))      )),regras_excluidas AS (    SELECT DISTINCT        DET.ORDEM,        DETCTACTB_EXC.PADRAO_CTACTB    FROM ESTR_DEMONSTRATIVOS EST    INNER JOIN DET_DEMONSTRATIVO DET ON EST.ID = DET.ID_ESTR_DEMONSTRATIVO    INNER JOIN DET_DEMONSTRATIVO_REFERENCIA DETREF ON DET.ID = DETREF.ID_DET_DEMONSTRATIVO    INNER JOIN DET_DEMONSTRATIVO_CTACTB_EXC DETCTACTB_EXC ON DETREF.ID = DETCTACTB_EXC.ID_DET_DEMONSTRATIVO_REFERENCIA    WHERE EST.ID = 1      AND DETREF.ANO_REFERENCIA = (          SELECT MAX(R.ANO_REFERENCIA)          FROM DET_DEMONSTRATIVO_REFERENCIA R          WHERE R.ID_DET_DEMONSTRATIVO = DET.ID            AND R.ANO_REFERENCIA <= YEAR(DATE(:VAR_DATA_REF_DRE))      )),contas_mapeadas AS (    SELECT        R.ORDEM,        R.NOME_GRUPO,        R.COD_NOTA_EXPLICATIVA,        R.SINAL,        CASE            WHEN TRIM(R.ORDEM) = '3.3.1' THEN B.saldo_final_ano_anterior            WHEN TRIM(R.ORDEM) = '3.3.2' THEN B.ytd_atu            WHEN R.ORDEM LIKE '1.%' OR R.ORDEM LIKE '2.%' OR R.ORDEM LIKE '3.%' THEN B.total_atu            ELSE B.ytd_atu        END AS valor_atu,        CASE            WHEN TRIM(R.ORDEM) = '3.3.1' THEN B.saldo_final_ano_retrasado            WHEN TRIM(R.ORDEM) = '3.3.2' THEN B.ytd_ant            WHEN R.ORDEM LIKE '1.%' OR R.ORDEM LIKE '2.%' OR R.ORDEM LIKE '3.%' THEN B.total_ant            ELSE B.ytd_ant        END AS valor_ant,        ROW_NUMBER() OVER(PARTITION BY B.CTACTB, R.ORDEM ORDER BY LENGTH(R.PADRAO_CTACTB) DESC) as rn    FROM base_bal B    JOIN regras_contas R ON B.CTACTB LIKE R.PADRAO_CTACTB    LEFT JOIN regras_excluidas E ON R.ORDEM = E.ORDEM AND B.CTACTB LIKE E.PADRAO_CTACTB    WHERE E.PADRAO_CTACTB IS NULL)SELECT    R.ORDEM,    R.NOME_GRUPO,    R.COD_NOTA_EXPLICATIVA,    SUM(IFNULL(M.valor_atu, 0) * M.SINAL) AS VLRLANC_ATU,    SUM(IFNULL(M.valor_ant, 0) * M.SINAL) AS VLRLANC_ANTFROM (SELECT DISTINCT ORDEM, NOME_GRUPO, COD_NOTA_EXPLICATIVA FROM regras_contas) RLEFT JOIN contas_mapeadas M ON R.ORDEM = M.ORDEM AND R.NOME_GRUPO = M.NOME_GRUPO AND M.rn = 1GROUP BY R.ORDEM, R.NOME_GRUPO, R.COD_NOTA_EXPLICATIVAORDER BY R.ORDEMLIMIT 500